export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResults = evaluateThresholds(thresholds, evaluations);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (Object.keys(thresholds).length > 0) {
    report.passed = thresholdResults.allPassed;
    report.thresholds = thresholdResults.entries;
  }

  return report;
}

function evaluateThresholds(thresholds, evaluations) {
  const entries = [];
  let allPassed = true;

  for (const [metricId, min] of Object.entries(thresholds)) {
    const metric = evaluations.find((m) => m.id === metricId);
    const score = metric?.score ?? null;
    const passed = score !== null && score >= min;

    if (!passed) {
      allPassed = false;
    }

    entries.push({
      metric: metricId,
      min,
      score,
      passed
    });
  }

  return { allPassed, entries };
}

