63	  evaluations,
64	  outputsPath,
65	  referencesPath,
66	  generatedAt = new Date().toISOString(),
67	  thresholds = {}
68	} = {}) {
69	  const totalSamples = evaluations.reduce((total, metric) => {
70	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
71	    return total;
72	  }, 0);
73	
74	  const thresholdResults = evaluateThresholds(thresholds, evaluations);
75	
76	  const report = {
