// Simulate the parseThresholds function from the CLI
function parseThresholds(thresholdStrings = []) {
  const thresholds = {};

  if (!thresholdStrings || thresholdStrings.length === 0) {
    return thresholds;
  }

  const validMetrics = ['exact_match', 'toxicity', 'length_variance'];
  const errors = [];

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      errors.push(`Malformed threshold: ${thresholdStr}. Expected format: <metric>=<number>`);
      continue;
    }

    const [, metricId, valueStr] = match;
    const value = Number.parseFloat(valueStr);

    if (!validMetrics.includes(metricId)) {
      errors.push(`Unknown metric: ${metricId}. Valid metrics: ${validMetrics.join(', ')}`);
      continue;
    }

    if (Number.isNaN(value) || value < 0 || value > 1) {
      errors.push(`Invalid threshold value: ${valueStr}. Threshold must be a number between 0 and 1.`);
      continue;
    }

    thresholds[metricId] = value;
  }

  return { thresholds, errors };
}

